func (t *PrinterSelection) flow() *tables.FlowRec {
	return &tables.FlowRec{
		Fields:     printerSelectionFields,
		Ref:        t.fieldRef,
		FlowFilter: t.flowFilterRef,
		DB:         t.db,
		Company:    t.company,
		Postgres:   t.dbType == database.DBTypePostgres,
		Outer:      "\"" + PrinterSelectionTableName + "\"",
		One:        t.flowFieldOf,
	}
}

// flowFieldOf calculates a FlowField for one record of a list (a record from the map, with
// this record's FlowFilters), in its map form
func (t *PrinterSelection) flowFieldOf(rec map[string]any, flowField int) any {
	one := &PrinterSelection{}
	one.InitWithDBType(t.db, t.company, t.dbType)
	for i := range printerSelectionFields.FlowFilters {
		*one.flowFilterRef(i) = *t.flowFilterRef(i)
	}
	one.FromMap(rec)
	f := one.flow()
	f.Calc(flowField)
	return f.MapValue(flowField)
}

